	D = new Float64Array( [ 1.0, 2.0 ] );
	E = new Float64Array( [ 1.0 ] );

	out = dlanst( 'max', -1, D, 1, E, 1 );
	t.strictEqual( out, 0.0, 'returns expected value' );

	out = dlanst( 'one-norm', -1, D, 1, E, 1 );
