tape( 'the function computes the Frobenius norm without intermediate overflow', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0e300, -1.0e300, 1.0e300 ] );
	E = new Float64Array( [ 1.0e300, -1.0e300 ] );

	// sqrt( 3*(1e300)^2 + 2*2*(1e300)^2 ) = sqrt(7)*1e300:
	expected = sqrt( 7.0 ) * 1.0e300;

	out = dlanst( 'frobenius-norm', 3, D, 1, E, 1 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function computes the Frobenius norm without intermediate underflow', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0e-300, -1.0e-300, 1.0e-300 ] );
	E = new Float64Array( [ 1.0e-300, -1.0e-300 ] );

	// sqrt( 3*(1e-300)^2 + 2*2*(1e-300)^2 ) = sqrt(7)*1e-300:
	expected = sqrt( 7.0 ) * 1.0e-300;

	out = dlanst( 'frobenius-norm', 3, D, 1, E, 1 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// When strideD = -1, elements are traversed in reverse
	D = new Float64Array( [ -1.0, 5.0, -2.0, 4.0 ] ); // reversed order
	E = new Float64Array( [ 2.0, -3.0, 1.0 ] ); // reversed order

	out = dlanst( 'max', 4, D, -1, E, -1 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, -1, E, -1 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	out = dlanst( 'infinity-norm', 4, D, -1, E, -1 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, -1, E, -1 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports non-unit strides', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// D has stride 2: elements at indices 0, 2, 4, 6
	D = new Float64Array( [ 4.0, 999.0, -2.0, 999.0, 5.0, 999.0, -1.0 ] );

	// E has stride 2: elements at indices 0, 2, 4
	E = new Float64Array( [ 1.0, 999.0, -3.0, 999.0, 2.0 ] );

	out = dlanst( 'max', 4, D, 2, E, 2 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, 2, E, 2 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	out = dlanst( 'infinity-norm', 4, D, 2, E, 2 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, 2, E, 2 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function handles all equal diagonal elements', function test( t ) {
	var out;
	var D;
	var E;

	D = new Float64Array( [ 5.0, 5.0, 5.0 ] );
	E = new Float64Array( [ 0.0, 0.0 ] );

	out = dlanst( 'max', 3, D, 1, E, 1 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 3, D, 1, E, 1 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	t.end();
});
